        },
        {
          "spanId": "sp8",
          "range": {
            "startChar": 2726,
            "endChar": 2759
          },
          "text": "Why the chain is plausible anyway",
          "voAssetId": "a_sp8_af9abe41",
          "alignmentAssetId": "al_sp8_9fd52c68"
        },
        {
